struct GrpcStream {Json session={{"open",false}};Bytes input,output;size_t output_pos=0;bool headers=false,end=false;std::string path;};
struct GrpcConnection {Lobby& lobby;SOCKET socket;nghttp2_session* h2=nullptr;std::map<int32_t,GrpcStream> streams;};
static ssize_t send_callback(nghttp2_session*,const uint8_t* data,size_t length,int,void* opaque){auto& conn=*static_cast<GrpcConnection*>(opaque);try{send_all(conn.socket,data,length);return ssize_t(length);}catch(...){return NGHTTP2_ERR_CALLBACK_FAILURE;}}
