static int data_callback(nghttp2_session* h2,uint8_t,int32_t stream,const uint8_t* data,size_t n,void* opaque){auto& conn=*static_cast<GrpcConnection*>(opaque);auto& s=conn.streams[stream];if(s.path!="/ics_xclient.XClientService/ProcessXClientMessage")return NGHTTP2_ERR_CALLBACK_FAILURE;if(s.input.size()+n>4*1024*1024)return NGHTTP2_ERR_CALLBACK_FAILURE;s.input.insert(s.input.end(),data,data+n);try{while(s.input.size()>=5){require(s.input[0]==0,"Compressed gRPC message unsupported");uint32_t size=(uint32_t(s.input[1])<<24)|(uint32_t(s.input[2])<<16)|(uint32_t(s.input[3])<<8)|s.input[4];require(size<=4*1024*1024,"gRPC message budget");if(s.input.size()<size_t(size)+5)break;Bytes payload(s.input.begin()+5,s.input.begin()+5+size);s.input.erase(s.input.begin(),s.input.begin()+5+size);auto request=conn.lobby.c.decode("ics_common.MessageWrapper",payload);std::lock_guard lock(conn.lobby.owner.mutex);conn.lobby.owner.record("lobby","C2S",payload,request);for(auto& response:conn.lobby.process(request,s.session)){auto b=conn.lobby.c.encode("ics_common.MessageWrapper",response);conn.lobby.owner.record("lobby","S2C",b,response);s.output.push_back(0);for(int i=3;i>=0;i--)s.output.push_back(uint8_t(b.size()>>(i*8)));s.output.insert(s.output.end(),b.begin(),b.end());}}if(!s.headers){auto nv=[](const char* n,const char* v){return nghttp2_nv{reinterpret_cast<uint8_t*>(const_cast<char*>(n)),reinterpret_cast<uint8_t*>(const_cast<char*>(v)),std::strlen(n),std::strlen(v),NGHTTP2_NV_FLAG_NONE};};nghttp2_nv headers[]={nv(":status","200"),nv("content-type","application/grpc"),nv("grpc-encoding","identity")};nghttp2_data_provider provider{};provider.read_callback=read_callback;require(nghttp2_submit_response(h2,stream,headers,3,&provider)==0,"gRPC response submit failed");s.headers=true;}else nghttp2_session_resume_data(h2,stream);return 0;}catch(const std::exception& e){conn.lobby.owner.event("lobby_error",{{"reason",e.what()}});return NGHTTP2_ERR_CALLBACK_FAILURE;}}
static int frame_callback(nghttp2_session* h2,const nghttp2_frame* f,void* opaque){auto& c=*static_cast<GrpcConnection*>(opaque);if((f->hd.type==NGHTTP2_DATA||f->hd.type==NGHTTP2_HEADERS)&&(f->hd.flags&NGHTTP2_FLAG_END_STREAM)){auto& s=c.streams[f->hd.stream_id];s.end=true;nghttp2_session_resume_data(h2,f->hd.stream_id);}return 0;}
