void Lobby::serve(SOCKET socket){GrpcConnection conn{*this,socket};nghttp2_session_callbacks* callbacks=nullptr;nghttp2_session_callbacks_new(&callbacks);nghttp2_session_callbacks_set_send_callback(callbacks,send_callback);nghttp2_session_callbacks_set_on_header_callback(callbacks,header_callback);nghttp2_session_callbacks_set_on_data_chunk_recv_callback(callbacks,data_callback);nghttp2_session_callbacks_set_on_frame_recv_callback(callbacks,frame_callback);nghttp2_session_callbacks_set_on_stream_close_callback(callbacks,close_callback);nghttp2_session_server_new(&conn.h2,callbacks,&conn);nghttp2_session_callbacks_del(callbacks);nghttp2_settings_entry settings[]={{NGHTTP2_SETTINGS_MAX_CONCURRENT_STREAMS,32}};nghttp2_submit_settings(conn.h2,NGHTTP2_FLAG_NONE,settings,1);nghttp2_session_send(conn.h2);std::array<uint8_t,65536> data;while(owner.lobby_service.running){int n=recv(socket,reinterpret_cast<char*>(data.data()),int(data.size()),0);if(n<=0)break;if(nghttp2_session_mem_recv(conn.h2,data.data(),size_t(n))<0||nghttp2_session_send(conn.h2)<0)break;}nghttp2_session_del(conn.h2);}
